const parseBool = (v, d = false) => {
  if (v === undefined || v === null || v === '') return d;
  if (typeof v === 'boolean') return v;
  return String(v).trim().toLowerCase() === 'true';
};

const parseIntSafe = (v, d = 25) => {
  const n = Number(v);
  return Number.isFinite(n) && n > 0 ? n : d;
};

const parseCsv = (v) => {
  if (!v) return [];
  return String(v)
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
};

return $input.all().map((item) => {
  const f = item.json;

  const companyList = parseCsv(f.company_list);
  const jobTitles = parseCsv(f.job_titles);
  const locations = parseCsv(f.locations);
  const industryIds = parseCsv(f.industry_ids);
  const employmentType = parseCsv(f.employment_type);
  const experienceLevels = parseCsv(f.experience_levels);
  const workplaceTypes = parseCsv(f.workplace_types);

  const config = {
    search_name: f.search_name || `form_${new Date().toISOString().slice(0, 10)}`,
    company_list: companyList,
    job_titles: jobTitles,
    locations,
    industry_ids: industryIds,
    employment_type: employmentType,
    experience_levels: experienceLevels,
    workplace_types: workplaceTypes,
    easy_apply: parseBool(f.easy_apply, false),
    under_10_applicants: parseBool(f.under_10_applicants, false),
    max_items: parseIntSafe(f.max_items, 25),
    country_filter: (f.country_filter || 'IN').toUpperCase(),
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  };

  const payload = {
    company: config.company_list,
    easyApply: config.easy_apply,
    employmentType: config.employment_type,
    experienceLevel: config.experience_levels,
    industryIds: config.industry_ids,
    jobTitles: config.job_titles,
    locations: config.locations,
    maxItems: config.max_items,
    under10Applicants: config.under_10_applicants,
    workplaceType: config.workplace_types
  };

  return {
    json: {
      search_name: config.search_name,
      country_filter: config.country_filter,
      apify_payload: payload,
      config_snapshot: config,
      execution_timestamp: new Date().toISOString()
    }
  };
});

const rows = $input.all();

const parseBool = (v, d = false) => {
  if (v === undefined || v === null || v === '') return d;
  if (typeof v === 'boolean') return v;
  return String(v).trim().toLowerCase() === 'true';
};

const parseIntSafe = (v, d = 25) => {
  const n = Number(v);
  return Number.isFinite(n) && n > 0 ? n : d;
};

const parseCsv = (v) => {
  if (!v) return [];
  return String(v)
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
};

const clean = rows
  .map((r) => r.json)
  .filter((r) => parseBool(r.enabled, false))
  .map((r) => ({
    search_name: r.search_name || 'default_search',
    company_list: parseCsv(r.company_list),
    job_titles: parseCsv(r.job_titles),
    locations: parseCsv(r.locations),
    industry_ids: parseCsv(r.industry_ids),
    employment_type: parseCsv(r.employment_type),
    experience_levels: parseCsv(r.experience_levels),
    workplace_types: parseCsv(r.workplace_types),
    easy_apply: parseBool(r.easy_apply, false),
    under_10_applicants: parseBool(r.under_10_applicants, false),
    max_items: parseIntSafe(r.max_items, 25),
    country_filter: r.country_filter || 'IN',
    created_at: r.created_at || new Date().toISOString(),
    updated_at: new Date().toISOString()
  }));

return clean.map((json) => ({ json }));

return $input.all().map((item) => {
  const c = item.json;

  const payload = {
    company: c.company_list,
    easyApply: c.easy_apply,
    employmentType: c.employment_type,
    experienceLevel: c.experience_levels,
    industryIds: c.industry_ids,
    jobTitles: c.job_titles,
    locations: c.locations,
    maxItems: c.max_items,
    under10Applicants: c.under_10_applicants,
    workplaceType: c.workplace_types
  };

  return {
    json: {
      search_name: c.search_name,
      country_filter: c.country_filter,
      apify_payload: payload,
      config_snapshot: c,
      execution_timestamp: new Date().toISOString()
    }
  };
});
